"""Render diagnose.py --json output as a private HTML page (internal only: it contains upcoming answers)."""
import json, sys, html
days = json.load(open(sys.argv[1]))
e = lambda s: html.escape(str(s))
def pct(s): return f"{s*100:.3g}%" if s >= 0.0001 else f"{s*100:.2g}%"
def table(rows, title):
    if not rows: return f"<p class=muted>{title}: none</p>"
    r = "".join(f"<tr><td>{e(x['answer'])}{'<span class=al> · ' + e(', '.join(x['aliases'])) + '</span>' if x['aliases'] else ''}</td><td>{pct(x['share'])}</td><td>{x['depth']} m</td><td class=muted>{e(x['source'])}</td></tr>" for x in rows)
    return f"<h5>{title}</h5><table><tr><th>Answer · other names</th><th>Est. share</th><th>Depth now</th><th>Source</th></tr>{r}</table>"
out = []
for d in days:
    t = d["totals"]
    qs = []
    for i, q in enumerate(d["questions"], 1):
        c = q["counts"]; ql = q["quality"]
        src = ", ".join(f"{k}: {v}" for k, v in q["sources"].items())
        qs.append(f"""<section class=q><h4>{i}. {e(q['prompt'])}</h4>
<p class=meta>{e(q['category'])} · {e(q['style'])} · difficulty {q['difficulty']} · quality {ql['score']} ({e(ql['status'])}) · top answer share {pct(ql['top_share'])}</p>
<div class=stats><span><b>{q['answers']}</b> answers</span><span><b>{q['aliases']}</b> other names</span><span><b>{c['common']}</b> common</span><span><b>{c['uncommon']}</b> uncommon</span><span><b>{c['obscure']}</b> obscure</span><span>depth range <b>{q['depth_range'][0]}–{q['depth_range'][1]} m</b></span></div>
<details><summary>Rules</summary><p><b>Player sees:</b> {e(' '.join(q['rules_player']))}</p><p><b>Accept:</b> {e('; '.join(q['accept']))}</p><p><b>Exclude:</b> {e('; '.join(q['exclude']))}</p><p><b>Granularity:</b> {e(q['granularity'])}</p><p><b>Dataset:</b> {e(q['dataset'] or 'none')} · <b>Sources:</b> {e(src)}</p></details>
{table(q['common'], 'Common (sample)')}{table(q['uncommon'], 'Uncommon (sample)')}{table(q['obscure'], 'Obscure (sample)')}
<ul class=lim>{''.join(f'<li>{e(l)}</li>' for l in q['limitations'])}</ul></section>""")
    out.append(f"<article><h3>Day {d['day']}</h3><p class=meta>{t['answers']:,} answers · {t['aliases']:,} other names · categories: {e(', '.join(t['categories']))} · styles: {e(', '.join(t['styles']))} · difficulties {t['difficulties']}</p>{''.join(qs)}</article>")
print(f"""<!doctype html><html lang=en><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Example Days Diagnostics</title>
<style>
:root{{--bg:#f7f8fa;--card:#fff;--text:#16202c;--muted:#5d6b7a;--line:#e1e6ec;--accent:#1f5fa8;--warn:#9a4b00}}
@media (prefers-color-scheme:dark){{:root{{--bg:#0c121b;--card:#131c28;--text:#e6edf5;--muted:#93a2b3;--line:#253244;--accent:#7fb3ee;--warn:#f0a35c}}}}
body{{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}}
main{{max-width:980px;margin:0 auto;padding:24px 16px 64px}} h1{{font-size:24px;margin:0 0 4px}} h3{{font-size:20px;margin:0 0 2px;color:var(--accent)}}
h4{{margin:0 0 2px;font-size:16px}} h5{{margin:12px 0 4px;font-size:13px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}}
.warn{{border-left:4px solid var(--warn);padding:10px 14px;background:var(--card);border-radius:6px;margin:12px 0 20px}}
article{{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:18px;margin:18px 0}}
.q{{border-top:1px solid var(--line);padding:14px 0 4px}} .meta,.muted{{color:var(--muted);font-size:13px;margin:0 0 6px}}
.stats{{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:13px;margin:4px 0 6px}}
table{{width:100%;border-collapse:collapse;font-size:13px}} th,td{{text-align:left;padding:3px 6px;border-bottom:1px solid var(--line);vertical-align:top}}
th{{color:var(--muted);font-weight:600}} td:nth-child(2),td:nth-child(3){{white-space:nowrap}} .al{{color:var(--muted)}}
details{{font-size:13px;margin:4px 0}} summary{{cursor:pointer;color:var(--accent)}} .lim{{font-size:12px;color:var(--muted);margin:8px 0 0;padding-left:18px}}
.wrap{{overflow-x:auto}}
</style></head><body><main>
<h1>Example days 16–22: internal diagnostics</h1>
<p class=muted>Generated by tools/content/diagnose.py from the private question bank and schedule.</p>
<div class=warn><b>Internal only. Contains upcoming answers.</b> Don't share this with players. Shares and depths are <b>estimates</b> (writers' judgement plus dataset priors), not player data: every depth here is capped (299 m with no evidence, 250 m for dataset-only answers) until real players answer. Samples are random picks from each band, so they are illustrative, not complete.</div>
<div class=wrap>{''.join(out)}</div></main></body></html>""")
